import { OrderStatus } from "@/modules/orders/contracts";
export { OrderStatus } from "@/modules/orders/contracts";
import {
  lastColumnLetter,
  type IGoogleSheetsService,
} from "@/externals/google/sheet";
import { ORDERS_SHEET_HEADERS } from "@/externals/google/sheet/sheets/orders/const";
import { USER_STATE_SHEET_HEADERS } from "@/externals/google/sheet/sheets/user-state/const";
import { createSortableId } from "../utils/createSortableId";

export type Order = {
  id: string;
  status: OrderStatus;
  seller: string;
  totalPrice: string;
  createdAt: string;
  updatedAt: string;
  deletedAt: string;
  createdBy: string;
  remark: string;
};

export enum UserStateFlowName {
  OrderCreate = "OrderCreate",
}

type UserState = {
  id: string;
  userId: string;
  flowname: UserStateFlowName;
  referenceId: string;
  state: OrderStatus;
  createdAt: string;
  updatedAt: string;
};

export async function createDraftOrder({
  googleSheetsService,
  createdBy,
}: {
  googleSheetsService: IGoogleSheetsService;
  createdBy: string;
}): Promise<Order> {
  const id = createSortableId();
  const now = new Date().toISOString();
  const order: Order = {
    id,
    status: OrderStatus.WaitingForBillImage,
    seller: "",
    totalPrice: "",
    createdAt: now,
    updatedAt: now,
    deletedAt: "",
    createdBy,
    remark: "",
  };

  await googleSheetsService.orders.appendRows(getOrdersAppendRange(), [
    [
      order.id,
      order.status,
      order.seller,
      order.totalPrice,
      order.remark,
      order.createdAt,
      order.updatedAt,
      order.deletedAt,
      order.createdBy,
    ],
  ]);

  await createOrderUserState({
    googleSheetsService,
    userId: createdBy,
    referenceId: order.id,
    now,
  });

  return order;
}

function getOrdersAppendRange(): string {
  return `A:${lastColumnLetter(ORDERS_SHEET_HEADERS.length - 1)}`;
}

async function createOrderUserState({
  googleSheetsService,
  userId,
  referenceId,
  now,
}: {
  googleSheetsService: IGoogleSheetsService;
  userId: string;
  referenceId: string;
  now: string;
}): Promise<UserState> {
  const id = await getNextUserStateRowNumber(googleSheetsService);
  const userState: UserState = {
    id: String(id),
    userId,
    flowname: UserStateFlowName.OrderCreate,
    referenceId,
    state: OrderStatus.WaitingForBillImage,
    createdAt: now,
    updatedAt: now,
  };

  await googleSheetsService.userState.appendRows(getUserStateAppendRange(), [
    [
      userState.id,
      userState.userId,
      userState.flowname,
      userState.referenceId,
      userState.state,
      userState.createdAt,
      userState.updatedAt,
    ],
  ]);

  return userState;
}

function getUserStateAppendRange(): string {
  return `A:${lastColumnLetter(USER_STATE_SHEET_HEADERS.length - 1)}`;
}

async function getNextUserStateRowNumber(
  googleSheetsService: IGoogleSheetsService,
): Promise<number> {
  const rows = await googleSheetsService.userState.readRows("A:A");
  return rows.length + 1;
}

