  id: string;
  productCode?: string;
  quoteQuantity?: number;
  deliveredQuantity?: number;
};

export type UpdatedOrderProduct = {
  id: string;
  productCode: string;
  quoteQuantity: string;
  deliveredQuantity: string;
  updatedAt: string;
};

export type ReplacedOrderProductImage = {
  id: string;
  imageUrl: string;
  updatedAt: string;
};

